{"cmd":"cat <<'JS' > /root/output/js/visualization.js
const tooltip = d3.select('#tooltip');
const bubbleContainer = d3.select('#bubble-chart');
const legendContainer = d3.select('#sector-legend');
const tableBody = d3.select('#stock-table tbody');

const palette = d3.schemeTableau10
  .concat(d3.schemeSet3)
  .concat(d3.schemePaired);

const formatMarketCap = (value) => {
  if (!isFinite(value)) return '—';
  const abs = Math.abs(value);
  const trim = (num) => String(num).replace(/\.0+$/, '').replace(/(\.\d*[1-9])0+$/, '$1');
  if (abs >= 1e12) return `${trim((value / 1e12).toFixed(2))}T`;
  if (abs >= 1e9) return `${trim((value / 1e9).toFixed(2))}B`;
  if (abs >= 1e6) return `${trim((value / 1e6).toFixed(2))}M`;
  if (abs >= 1e3) return `${trim((value / 1e3).toFixed(2))}K`;
  return trim(value.toFixed(0));
};

const computeVolatility = (rows) => {
  const prices = rows
    .map((row) => +row['Adjusted Close'] || +row.Close)
    .filter((value) => Number.isFinite(value));
  if (prices.length < 5) return NaN;
  const recent = prices.slice(-60);
  const returns = [];
  for (let i = 1; i < recent.length; i += 1) {
    returns.push(recent[i] / recent[i - 1] - 1);
  }
  if (!returns.length) return NaN;
  const mean = d3.mean(returns);
  const variance = d3.mean(returns.map((r) => (r - mean) ** 2));
  return Math.sqrt(variance);
};

const loadPriceStats = async (data) => {
  const stats = await Promise.all(
    data.map(async (stock) => {
      try {
        const rows = await d3.csv(`data/indiv-stock/${stock.ticker}.csv`);
        return computeVolatility(rows);
      } catch (err) {
        return NaN;
      }
    })
  );
  const valid = stats.filter((value) => Number.isFinite(value));
  const scale = valid.length
    ? d3.scaleLinear().domain(d3.extent(valid)).range([1, 3.2])
    : () => 1.4;

  data.forEach((stock, index) => {
    stock.volatility = stats[index];
    stock.strokeWidth = Number.isFinite(stock.volatility)
      ? scale(stock.volatility)
      : 1.4;
  });
};

const createVisualization = async () => {
  const raw = await d3.csv('data/stock-descriptions.csv');
  const data = raw
    .map((d) => ({
      ticker: d.ticker,
      sector: d.sector,
      fullName: d['full name'],
      marketCap: +d.marketCap,
      country: d.country,
      website: d.website,
    }))
    .filter((d) => d.ticker);

  data.forEach((d) => {
    d.isETF = !Number.isFinite(d.marketCap) || d.sector === 'ETF';
  });

  await loadPriceStats(data);

  const sectors = Array.from(new Set(data.map((d) => d.sector))).sort();
  const colorScale = d3.scaleOrdinal(sectors, palette);

  const capValues = data
    .filter((d) => Number.isFinite(d.marketCap))
    .map((d) => d.marketCap);
  const radiusScale = d3
    .scaleSqrt()
    .domain(d3.extent(capValues))
    .range([12, 44]);

  data.forEach((d) => {
    d.radius = d.isETF ? 16 : radiusScale(d.marketCap);
  });

  const svg = bubbleContainer
    .append('svg')
    .attr('class', 'bubble-svg')
    .attr('role', 'img')
    .attr('aria-label', 'Bubble chart of stocks clustered by sector');

  const nodes = svg
    .selectAll('g.node')
    .data(data, (d) => d.ticker)
    .join((enter) => {
      const node = enter.append('g').attr('class', 'node');
      node
        .append('circle')
        .attr('class', 'bubble')
        .attr('r', (d) => d.radius)
        .attr('fill', (d) => colorScale(d.sector))
        .attr('stroke-width', (d) => d.strokeWidth)
        .attr('opacity', 0.92);
      node
        .append('text')
        .attr('text-anchor', 'middle')
        .attr('dy', '0.35em')
        .text((d) => d.ticker)
        .style('font-size', (d) => `${Math.max(8, d.radius / 2.2)}px`);
      return node;
    });

  let selectedTicker = null;

  const setSelected = (ticker) => {
    selectedTicker = selectedTicker === ticker ? null : ticker;
    nodes.classed('selected', (d) => d.ticker === selectedTicker);
    tableBody
      .selectAll('tr')
      .classed('selected', (d) => d.ticker === selectedTicker);
    if (selectedTicker) {
      const rowNode = tableBody
        .selectAll('tr')
        .filter((d) => d.ticker === selectedTicker)
        .node();
      if (rowNode) {
        rowNode.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }
  };

  nodes
    .on('click', (event, d) => {
      setSelected(d.ticker);
    })
    .on('mouseover', (event, d) => {
      if (d.isETF) return;
      tooltip
        .style('opacity', 1)
        .html(
          `<strong>${d.ticker}</strong>${d.fullName}<br/>Sector: ${d.sector}`
        );
    })
    .on('mousemove', (event) => {
      const [x, y] = d3.pointer(event, document.body);
      tooltip.style('left', `${x}px`).style('top', `${y}px`);
    })
    .on('mouseout', () => {
      tooltip.style('opacity', 0);
    });

  const tableRows = tableBody
    .selectAll('tr')
    .data(
      data.sort((a, b) => {
        const aCap = Number.isFinite(a.marketCap) ? a.marketCap : -1;
        const bCap = Number.isFinite(b.marketCap) ? b.marketCap : -1;
        return bCap - aCap;
      }),
      (d) => d.ticker
    )
    .join('tr')
    .on('click', (event, d) => {
      setSelected(d.ticker);
    });

  tableRows
    .append('td')
    .text((d) => d.ticker);
  tableRows
    .append('td')
    .text((d) => d.fullName || '—');
  tableRows
    .append('td')
    .text((d) => d.sector || '—');
  tableRows
    .append('td')
    .text((d) => formatMarketCap(d.marketCap));

  legendContainer
    .selectAll('div.legend-item')
    .data(sectors)
    .join('div')
    .attr('class', 'legend-item')
    .call((legendItem) => {
      legendItem
        .append('span')
        .attr('class', 'legend-swatch')
        .style('background', (d) => colorScale(d));
      legendItem.append('span').text((d) => d);
    });

  const applyForces = () => {
    const width = bubbleContainer.node().clientWidth || 600;
    const height = Math.max(480, Math.min(620, width * 0.75));
    svg.attr('viewBox', `0 0 ${width} ${height}`);

    const centerX = width / 2;
    const centerY = height / 2;
    const clusterRadius = Math.min(width, height) * 0.25;
    const clusterPositions = new Map();
    sectors.forEach((sector, index) => {
      const angle = (index / sectors.length) * Math.PI * 2;
      clusterPositions.set(sector, {
        x: centerX + clusterRadius * Math.cos(angle),
        y: centerY + clusterRadius * Math.sin(angle),
      });
    });

    if (!applyForces.simulation) {
      applyForces.simulation = d3
        .forceSimulation(data)
        .force(
          'x',
          d3
            .forceX((d) => clusterPositions.get(d.sector).x)
            .strength(0.08)
        )
        .force(
          'y',
          d3
            .forceY((d) => clusterPositions.get(d.sector).y)
            .strength(0.08)
        )
        .force('collide', d3.forceCollide((d) => d.radius + 1.6))
        .force('charge', d3.forceManyBody().strength(-3))
        .force('center', d3.forceCenter(centerX, centerY))
        .on('tick', () => {
          nodes.attr('transform', (d) => `translate(${d.x},${d.y})`);
        });
    } else {
      applyForces.simulation
        .force(
          'x',
          d3
            .forceX((d) => clusterPositions.get(d.sector).x)
            .strength(0.08)
        )
        .force(
          'y',
          d3
            .forceY((d) => clusterPositions.get(d.sector).y)
            .strength(0.08)
        )
        .force('center', d3.forceCenter(centerX, centerY))
        .alpha(0.9)
        .restart();
    }
  };

  applyForces();

  const resizeObserver = new ResizeObserver(() => {
    applyForces();
  });
  resizeObserver.observe(bubbleContainer.node());
};

createVisualization();
JS"}

